173	#[derive(Debug)]
174	struct GrEvent {
175	    req: usize,
176	    base: usize, // global draw index of the first byte this call hands out
177	    ret: i64,    // negative: the call failed with the injected errno
178	}
179	
180	impl GrEvent {
181	    fn failed(&self) -> bool {
182	        self.ret < 0
183	    }
184	
185	    fn delivered(&self) -> usize {
186	        if self.ret > 0 { self.ret as usize } else { 0 }
187	    }
