197	/// The GETRANDOM lines of the trace, in call order.
198	fn getrandom_events(trace: &Path) -> Vec<GrEvent> {
199	    let text = fs::read_to_string(trace).unwrap();
200	    text.lines()
201	        .filter_map(|line| {
202	            let mut parts = line.split_whitespace();
203	            if parts.next() != Some("GETRANDOM") {
204	                return None;
205	            }
206	            let mut req = None;
207	            let mut base = None;
208	            let mut ret = None;
209	            for kv in parts {
210	                let (k, v) = kv.split_once('=')?;
211	                match k {
212	                    "req" => req = v.parse().ok(),
213	                    "base" => base = v.parse().ok(),
214	                    "ret" => ret = v.parse().ok(),
215	                    _ => {}
