290	    }
291	    if (cfg_mode == MODE_OFF)
292	        return;
293	
294	    if ((v = getenv("WRAPFILE_TEST_TRACE_FILE")) && v[0])
295	        trace_fd = open(v, O_WRONLY | O_CREAT | O_APPEND | O_CLOEXEC, 0600);
296	
297	    memset(&sa, 0, sizeof(sa));
298	    sa.sa_sigaction = on_sigsys;
299	    sa.sa_flags = SA_SIGINFO;
300	    sigemptyset(&sa.sa_mask);
301	    if (sigaction(SIGSYS, &sa, NULL) != 0) {
302	        trace_str("TRAP unavailable errno=SIGACTION\n");
303	        cfg_mode = MODE_OFF;
304	        return;
305	    }
306	
307	    if (prctl(PR_SET_NO_NEW_PRIVS, 1, 0, 0, 0) != 0 ||
308	        prctl(PR_SET_SECCOMP, SECCOMP_MODE_FILTER, &prog) != 0) {
309	        /* No seccomp on this kernel: leave the real random source alone
310	         * and let the tests skip themselves. */
311	        trace_str("TRAP unavailable errno=SECCOMP\n");
312	        cfg_mode = MODE_OFF;
313	        return;
314	    }
315	
316	    trace_str("TRAP armed\n");
317	}
