128	/* Descriptor table: fds the guest created with O_CREAT. */
129	#define FD_MAX 1024
130	static unsigned char tracked[FD_MAX];
131	static unsigned char written[FD_MAX];
132	static unsigned char eintr_left[FD_MAX];
