156	static void load_config(void)
157	{
158	    static int loaded = 0;
159	    if (loaded)
160	        return;
161	    loaded = 1;
162	
163	    const char *v;
164	    if ((v = getenv("WRAPFILE_TEST_FAIL_FCHMOD")) && v[0] == '1')
165	        cfg_fail_fchmod = 1;
166	    if ((v = getenv("WRAPFILE_TEST_FAIL_FSTAT")) && v[0] == '1')
167	        cfg_fail_fstat = 1;
168	    if ((v = getenv("WRAPFILE_TEST_TRACE_FILE")))
169	        (void)v; /* opened lazily on first trace() */
170	    if ((v = getenv("WRAPFILE_TEST_LIE_MODE")) && v[0] != '\0')
171	        cfg_lie_mode = (int)strtol(v, NULL, 8);
172	    if ((v = getenv("WRAPFILE_TEST_PARTIAL_WRITE")) && v[0] != '\0')
173	        cfg_partial_write = strtol(v, NULL, 10);
174	    if ((v = getenv("WRAPFILE_TEST_WRITE_EINTR")) && v[0] != '\0')
175	        cfg_write_eintr = atoi(v);
176	    if ((v = getenv("WRAPFILE_TEST_FAIL_WRITE_AFTER")) && v[0] != '\0')
177	        cfg_fail_write_after = strtol(v, NULL, 10);
178	    if ((v = getenv("WRAPFILE_TEST_WRITE_ZERO_AFTER")) && v[0] != '\0')
179	        cfg_write_zero_after = strtol(v, NULL, 10);
180	    if ((v = getenv("WRAPFILE_TEST_FAIL_FSYNC")) && v[0] == '1')
181	        cfg_fail_fsync = 1;
182	    if ((v = getenv("WRAPFILE_TEST_FAIL_CLOSE")) && v[0] == '1')
183	        cfg_fail_close = 1;
184	    if ((v = getenv("WRAPFILE_TEST_CLOSE_EINTR")) && v[0] == '1')
185	        cfg_close_eintr = 1;
186	    if ((v = getenv("WRAPFILE_TEST_FAIL_UNLINK")) && v[0] == '1')
187	        cfg_fail_unlink = 1;
188	    if ((v = getenv("WRAPFILE_TEST_TRACE_BYTES")) && v[0] == '1')
189	        cfg_trace_bytes = 1;
