225	/* ----- per-descriptor helpers ----- */
226	
227	static fstat_fn get_real_fstat(void)
228	{
229	    if (!real_fstat)
230	        real_fstat = (fstat_fn)dlsym(RTLD_NEXT, "fstat");
231	    return real_fstat;
232	}
233	
234	static int is_tracked(int fd)
235	{
236	    return fd >= 0 && fd < FD_MAX && tracked[fd];
237	}
238	
239	/* malloc'd lowercase hex of n bytes, or NULL. Caller frees. */
240	static char *hex_encode(const unsigned char *p, size_t n)
241	{
242	    static const char digits[] = "0123456789abcdef";
243	    char *hex = malloc(n * 2 + 1);
244	    if (!hex)
245	        return NULL;
246	    for (size_t i = 0; i < n; i++) {
247	        hex[i * 2] = digits[p[i] >> 4];
248	        hex[i * 2 + 1] = digits[p[i] & 0xf];
249	    }
250	    hex[n * 2] = '\0';
251	    return hex;
252	}
253	
254	static void note_created(int fd)
255	{
256	    if (fd < 0 || fd >= FD_MAX)
257	        return;
258	    tracked[fd] = 1;
259	    written[fd] = 0;
260	    eintr_left[fd] = (cfg_write_eintr > 0 && cfg_write_eintr < 256)
261	                         ? (unsigned char)cfg_write_eintr
262	                         : 0;
263	    written_total[fd] = 0;
264	
265	    struct stat st;
266	    fstat_fn fn = get_real_fstat();
267	    if (fn && fn(fd, &st) == 0) {
268	        trace("BORN fd=%d mode=0%04o\n", fd,
269	              (unsigned)(st.st_mode & 07777));
270	    }
271	}
