1	//! Regression coverage for keygen's write/sync contract on Unix: what must
2	//! hold while the 32 key bytes are being saved, and when saving cannot
3	//! complete (see README "文件权限" for the permission side, covered in
4	//! keygen_permissions.rs).
5	//!
6	//! What is protected here:
7	//!
8	//! * Partial writes: if the kernel only accepts part of the buffer per
9	//!   write() call, the remaining bytes still land -- no byte already written
10	//!   is duplicated, no later byte is skipped. The final file is exactly the
11	//!   32 raw key bytes (no newline, header, or trailer), mode 0600.
12	//! * Recoverable interruption: write() failing with EINTR and then
13	//!   succeeding still completes the same generation with exit code 0.
14	//! * Success is only reported after every byte is written *and* fsynced:
15	//!   exit 0, the usual "Key saved to ..." line on stdout, empty stderr.
16	//! * Unrecoverable write error after some bytes landed, and fsync failure
17	//!   after all bytes landed: exit 1, stderr explains the failure (naming
18	//!   the target), stdout carries no success message, the file created by
19	//!   this invocation is removed, and neither the parent directory's
20	//!   permissions nor pre-existing siblings are touched. Key bytes never
21	//!   appear on stdout/stderr, on success or on failure.
22	//! * Zero-byte write: write() accepting 0 bytes while bytes remain -- no
23	//!   progress, yet no errno either -- is neither success nor a recoverable
24	//!   interruption. Whether it happens before any byte landed or midway,
25	//!   the command must end (not hang in the save loop) with exit 1, an
26	//!   explanation naming the target on stderr, empty stdout, and no file
27	//!   left at the target: no empty file, no partial key, no zero-padded
28	//!   32-byte stand-in.
29	//! * Close-stage failure: all 32 bytes written and fsynced, then close()
30	//!   reporting an unrecoverable error is still a failed save -- exit 1,
31	//!   empty stdout, stderr naming the target and the close-stage error, and
32	//!   the file removed even though it holds 32 bytes with mode 0600. If the
33	//!   system also refuses the removal, stderr keeps the close failure and
34	//!   additionally warns that cleanup did not complete and this run's key
35	//!   file may remain at the target; the parent directory's permissions are
36	//!   never loosened to force the cleanup, and the key is not stashed under
37	//!   another name. A close() that merely reports EINTR after releasing the
38	//!   descriptor is not a failure: the save is reported as usual, exit 0.
39	//! * Refused cleanup after a write/fsync/permission-stage failure: the same
40	//!   reporting rule as for the close stage -- exit 1, empty stdout, stderr
41	//!   keeps the original failure reason (unfinished write, failed sync, or
42	//!   the 0600 permission problem), additionally reports the failed cleanup
43	//!   and its reason, and warns that this run's file (even an empty one) may
44	//!   still be present at the target so the user can check and remove it.
45	//!
46	//! The faults are injected by the LD_PRELOAD shim (tests/support/permfail),
47	//! which also traces every write()/fsync() on the key descriptor so the
48	//! byte stream can be checked for gaps, duplicates, and leaks.
49	#![cfg(unix)]
50	
51	mod common;
52	
53	use std::collections::HashMap;
54	use std::fs;
55	use std::os::unix::fs::{MetadataExt, PermissionsExt};
56	use std::path::{Path, PathBuf};
57	use std::process::Command;
58	use std::sync::atomic::{AtomicU64, Ordering};
59	
60	const KEY_LEN: usize = 32;
61	const MODE_0600: u32 = 0o600;
62	const UMASKS: [u32; 3] = [0o022, 0o000, 0o777];
63	
64	fn bin() -> PathBuf {
65	    PathBuf::from(env!("CARGO_BIN_EXE_wrapfile"))
66	}
67	
68	fn permfail_so() -> Option<PathBuf> {
69	    common::permfail_so()
70	}
71	
72	// ---------------------------------------------------------------------------
73	// scratch directory
74	// ---------------------------------------------------------------------------
75	
76	struct Tmp {
77	    path: PathBuf,
78	}
79	
80	impl Tmp {
81	    fn new(label: &str) -> Tmp {
82	        static SEQ: AtomicU64 = AtomicU64::new(0);
83	        let path = std::env::temp_dir().join(format!(
84	            "wrapfile-keygen-write-tests-{}-{}-{}",
85	            std::process::id(),
86	            label,
87	            SEQ.fetch_add(1, Ordering::Relaxed)
88	        ));
89	        fs::create_dir_all(&path).unwrap();
90	        fs::set_permissions(&path, fs::Permissions::from_mode(0o700)).unwrap();
91	        Tmp { path }
92	    }
93	
94	    fn child(&self, name: impl AsRef<Path>) -> PathBuf {
95	        self.path.join(name)
96	    }
97	}
98	
99	impl Drop for Tmp {
100	    fn drop(&mut self) {
101	        let _ = fs::set_permissions(&self.path, fs::Permissions::from_mode(0o700));
102	        let _ = fs::remove_dir_all(&self.path);
103	    }
104	}
105	
106	// ---------------------------------------------------------------------------
107	// running the binary
108	// ---------------------------------------------------------------------------
109	
110	struct Run {
111	    rc: i32,
112	    out: Vec<u8>,
113	    err: Vec<u8>,
114	}
115	
116	/// Run `wrapfile keygen <key>` after setting the umask inside a /bin/sh
117	/// wrapper, with the permfail shim preloaded and a trace file configured.
118	fn run_keygen(key: &Path, umask: u32, so: &Path, extra_env: &[(&str, &str)], trace: &Path) -> Run {
119	    let mut cmd = Command::new("/bin/sh");
120	    cmd.arg("-c")
121	        .arg(format!("umask {umask:04o}; exec \"$@\""))
122	        .arg("sh")
123	        .arg(bin())
124	        .arg("keygen")
125	        .arg(key)
126	        .env("LD_PRELOAD", so)
127	        .env("WRAPFILE_TEST_TRACE_FILE", trace);
128	    for (k, v) in extra_env {
129	        cmd.env(k, v);
130	    }
131	    let o = cmd.output().unwrap();
132	    Run {
133	        rc: o.status.code().unwrap_or(-1),
134	        out: o.stdout,
135	        err: o.stderr,
136	    }
137	}
138	
139	// ---------------------------------------------------------------------------
140	// shim trace log
141	// ---------------------------------------------------------------------------
142	
143	struct Event {
144	    kind: String,
145	    attrs: HashMap<String, String>,
146	}
147	
148	impl Event {
149	    fn get(&self, key: &str) -> Option<&str> {
150	        self.attrs.get(key).map(String::as_str)
151	    }
152	
153	    fn ret(&self) -> Option<i64> {
154	        self.get("ret").and_then(|v| v.parse().ok())
155	    }
156	
157	    fn off(&self) -> Option<u64> {
158	        self.get("off").and_then(|v| v.parse().ok())
159	    }
160	
161	    fn hex_bytes(&self) -> Option<Vec<u8>> {
162	        let hex = self.get("hex")?;
163	        assert_eq!(hex.len() % 2, 0, "odd hex in trace line");
164	        Some(
165	            (0..hex.len() / 2)
166	                .map(|i| u8::from_str_radix(&hex[i * 2..i * 2 + 2], 16).unwrap())
167	                .collect(),
168	        )
169	    }
170	}
171	
172	fn parse_trace(path: &Path) -> Vec<Event> {
173	    let text = fs::read_to_string(path).unwrap();
174	    text.lines()
175	        .map(|line| {
176	            let mut it = line.split_whitespace();
177	            let kind = it.next().unwrap_or("").to_string();
178	            let attrs = it
179	                .filter_map(|kv| kv.split_once('=').map(|(k, v)| (k.to_string(), v.to_string())))
180	                .collect();
181	            Event { kind, attrs }
182	        })
183	        .collect()
184	}
185	
186	/// Create the trace file up front (mode 0644) so that it stays readable even
187	/// when the child runs under umask 0777 -- the shim opens it O_APPEND.
188	fn prepare_trace(dir: &Path, name: impl AsRef<Path>) -> PathBuf {
189	    let p = dir.join(name);
190	    fs::File::create(&p).unwrap();
191	    fs::set_permissions(&p, fs::Permissions::from_mode(0o644)).unwrap();
192	    p
193	}
194	
195	/// The successful write() calls, in call order: (offset, bytes landed, bytes).
196	fn successful_writes(events: &[Event]) -> Vec<(u64, u64, Option<Vec<u8>>)> {
197	    events
198	        .iter()
199	        .filter(|e| e.kind == "WRITE" && e.ret().is_some_and(|r| r > 0))
200	        .map(|e| {
201	            (
202	                e.off().expect("WRITE event needs off="),
203	                e.ret().unwrap() as u64,
204	                e.hex_bytes(),
205	            )
206	        })
207	        .collect()
208	}
209	
210	/// The landed writes must tile [0, total) exactly: the first starts at 0,
211	/// each continues where the previous ended -- no byte written twice, none
212	/// skipped.
213	fn assert_writes_tile(writes: &[(u64, u64, Option<Vec<u8>>)], total: usize, context: &str) {
214	    assert!(!writes.is_empty(), "{context}: no bytes were ever written");
215	    let mut expect = 0u64;
216	    for (off, n, _) in writes {
217	        assert_eq!(
218	            *off, expect,
219	            "{context}: write at offset {off} overlaps or leaves a gap (expected {expect})"
220	        );
221	        expect += n;
222	    }
223	    assert_eq!(
224	        expect as usize, total,
225	        "{context}: writes must add up to exactly {total} bytes, got {expect}"
226	    );
227	}
228	
229	fn reconstruct(writes: &[(u64, u64, Option<Vec<u8>>)]) -> Vec<u8> {
230	    writes
231	        .iter()
232	        .flat_map(|(_, _, hex)| hex.clone().expect("TRACE_BYTES must be on"))
233	        .collect()
234	}
235	
236	/// The write() calls that accepted 0 bytes while reporting no error.
237	fn zero_writes<'a>(events: &'a [Event]) -> Vec<&'a Event> {
238	    events
239	        .iter()
240	        .filter(|e| e.kind == "WRITE" && e.ret() == Some(0))
241	        .collect()
242	}
243	
244	/// Bytes the program handed to write() calls that accepted none of them.
245	fn rejected_offerings(events: &[Event]) -> Vec<u8> {
246	    zero_writes(events)
247	        .iter()
248	        .flat_map(|e| e.hex_bytes().expect("TRACE_BYTES must be on"))
249	        .collect()
250	}
251	
252	// ---------------------------------------------------------------------------
253	// filesystem assertions
254	// ---------------------------------------------------------------------------
255	
256	fn mode_of(path: &Path) -> u32 {
257	    fs::symlink_metadata(path).unwrap().mode() & 0o7777
258	}
259	
260	fn contains_slice(haystack: &[u8], needle: &[u8]) -> bool {
261	    needle.is_empty() || haystack.windows(needle.len()).any(|w| w == needle)
262	}
263	
264	/// The full success contract: exit 0, empty stderr, only the save-location
265	/// line on stdout, and exactly 32 raw key bytes in a 0600 file that leaks
266	/// nowhere.
267	fn assert_success(key: &Path, run: &Run) -> Vec<u8> {
268	    assert_eq!(run.rc, 0, "stderr={}", String::from_utf8_lossy(&run.err));
269	    assert!(
270	        run.err.is_empty(),
271	        "stderr must be empty on success, got {}",
272	        String::from_utf8_lossy(&run.err)
273	    );
274	    assert_eq!(
275	        run.out,
276	        format!("Key saved to {}\n", key.display()).into_bytes(),
277	        "stdout must be exactly the save-location message"
278	    );
279	
280	    let meta = fs::metadata(key).expect("key file must exist on success");
281	    assert_eq!(meta.len() as usize, KEY_LEN, "key must be exactly 32 bytes");
282	    assert_eq!(
283	        meta.mode() & 0o7777,
284	        MODE_0600,
285	        "key file mode must be exactly 0600"
286	    );
287	
288	    let bytes = fs::read(key).unwrap();
289	    assert_eq!(bytes.len(), KEY_LEN);
290	    assert!(bytes.iter().any(|&b| b != 0), "key must not be all zeroes");
291	    assert!(
292	        !contains_slice(&run.out, &bytes) && !contains_slice(&run.err, &bytes),
293	        "key bytes must never appear on stdout/stderr"
294	    );
295	    bytes
296	}
297	
298	/// The failure contract shared by the write-error and fsync-error tests:
299	/// exit 1, an explanation on stderr, no success output, no leaked key
300	/// material, and no trace of this invocation left in the parent directory.
301	fn assert_failed_cleanly(
302	    key: &Path,
303	    run: &Run,
304	    dir: &Path,
305	    allowed_entries: &[&str],
306	    leaked_candidate: &[u8],
307	) {
308	    assert_eq!(run.rc, 1, "an unfinishable save must exit 1");
309	    assert!(
310	        run.out.is_empty(),
311	        "no success message may be printed on failure, got {}",
312	        String::from_utf8_lossy(&run.out)
313	    );
314	    assert!(!run.err.is_empty(), "stderr must explain the failure");
315	    let stderr = String::from_utf8_lossy(&run.err);
316	    assert!(
317	        stderr.contains(&key.display().to_string()),
318	        "stderr should name the target path, got: {stderr}"
319	    );
320	    assert!(
321	        !contains_slice(&run.out, leaked_candidate)
322	            && !contains_slice(&run.err, leaked_candidate),
323	        "key material must never leak to stdout/stderr, even on failure"
324	    );
325	
326	    assert!(
327	        !key.exists(),
328	        "the file this invocation created must be removed after the failure"
329	    );
330	    let mut leftovers: Vec<String> = fs::read_dir(dir)
331	        .unwrap()
332	        .map(|e| e.unwrap().file_name().to_string_lossy().into_owned())
333	        .filter(|n| !allowed_entries.contains(&n.as_str()))
334	        .collect();
335	    leftovers.sort();
336	    assert!(leftovers.is_empty(), "unexpected leftover files: {leftovers:?}");
337	}
338	
339	/// Key material must not surface on stdout/stderr in any encoding: not as
340	/// raw bytes, and not as a hex (or other text) rendering.
341	fn assert_key_material_not_leaked(run: &Run, material: &[u8], what: &str) {
342	    assert!(
343	        !contains_slice(&run.out, material) && !contains_slice(&run.err, material),
344	        "{what} must never appear on stdout/stderr as raw bytes"
345	    );
346	    let hex: String = material.iter().map(|b| format!("{b:02x}")).collect();
347	    let out = String::from_utf8_lossy(&run.out);
348	    let err = String::from_utf8_lossy(&run.err);
349	    assert!(
350	        !out.contains(&hex) && !err.contains(&hex),
351	        "{what} must never appear on stdout/stderr in hex form"
352	    );
353	}
354	
355	/// The contract when the save fails AND the system refuses to remove this
356	/// run's file: exit 1, empty stdout, stderr names the target, keeps the
357	/// original failure reason (`stage_reason`), reports the refused cleanup,
358	/// and warns that this run's file may remain -- and the file really does
359	/// remain, with nothing stashed under another name.
360	fn assert_failed_with_residue(
361	    key: &Path,
362	    run: &Run,
363	    dir: &Path,
364	    allowed_entries: &[&str],
365	    stage_reason: &str,
366	) {
367	    assert_eq!(run.rc, 1, "a failed save with refused cleanup must exit 1");
368	    assert!(
369	        run.out.is_empty(),
370	        "no success message may be printed, got {}",
371	        String::from_utf8_lossy(&run.out)
372	    );
373	    let stderr = String::from_utf8_lossy(&run.err);
374	    assert!(
375	        stderr.contains(&key.display().to_string()),
376	        "stderr should name the target path, got: {stderr}"
377	    );
378	    // The original failure reason is still reported...
379	    assert!(
380	        stderr.contains(stage_reason),
381	        "stderr must keep the original failure reason ({stage_reason:?}), got: {stderr}"
382	    );
383	    // ...the cleanup failure is reported too (not silently dropped, and not
384	    // replacing the save error)...
385	    assert!(
386	        stderr.contains("cleanup"),
387	        "stderr must report the failed cleanup, got: {stderr}"
388	    );
389	    // ...and the user is told this run's file may remain -- never that it
390	    // is gone.
391	    assert!(
392	        stderr.contains("may still be present"),
393	        "stderr must warn that this run's file may remain, got: {stderr}"
394	    );
395	
396	    // The refused removal means this run's file really is still at the
397	    // target -- the warning above is what keeps it from being mistaken for
398	    // a successfully saved key.
399	    assert!(
400	        key.exists(),
401	        "with unlink refused, this run's file remains at the target"
402	    );
403	    // Nothing was stashed under another name and no other residue appeared.
404	    let mut expected: Vec<String> = allowed_entries.iter().map(|s| s.to_string()).collect();
405	    expected.push(key.file_name().unwrap().to_string_lossy().into_owned());
406	    expected.sort();
407	    let mut entries: Vec<String> = fs::read_dir(dir)
408	        .unwrap()
409	        .map(|e| e.unwrap().file_name().to_string_lossy().into_owned())
410	        .collect();
411	    entries.sort();
412	    assert_eq!(entries, expected, "no renamed copy or other leftover may appear");
413	}
414	
415	// A pre-existing object that must survive a failed keygen byte-for-byte.
416	struct Sentinel {
417	    path: PathBuf,
418	    bytes: Vec<u8>,
419	    mode: u32,
420	    inode: u64,
421	}
422	
423	impl Sentinel {
424	    fn file(dir: &Path, name: &str, bytes: &[u8], mode: u32) -> Sentinel {
425	        let path = dir.join(name);
426	        fs::write(&path, bytes).unwrap();
427	        fs::set_permissions(&path, fs::Permissions::from_mode(mode)).unwrap();
428	        let meta = fs::metadata(&path).unwrap();
429	        Sentinel { path, bytes: bytes.to_vec(), mode, inode: meta.ino() }
430	    }
431	
432	    fn assert_untouched(&self) {
433	        let meta = fs::metadata(&self.path).expect("sentinel must still exist");
434	        assert_eq!(meta.ino(), self.inode, "sentinel inode changed (object replaced)");
435	        assert_eq!(meta.mode() & 0o7777, self.mode, "sentinel permissions changed");
436	        assert_eq!(fs::read(&self.path).unwrap(), self.bytes, "sentinel contents changed");
437	    }
438	}
439	
440	// ---------------------------------------------------------------------------
441	// tests
442	// ---------------------------------------------------------------------------
443	
444	#[test]
445	fn partial_writes_save_the_full_key_exactly_once() {
446	    let Some(so) = permfail_so() else {
447	        eprintln!("skipping: permfail shim not available on this target");
448	        return;
449	    };
450	
451	    for umask in UMASKS {
452	        let tmp = Tmp::new("partial");
453	        let key = tmp.child("key");
454	        let trace = prepare_trace(&tmp.path, "trace.log");
455	
456	        // The kernel accepts only one byte per write() call.
457	        let run = run_keygen(
458	            &key,
459	            umask,
460	            &so,
461	            &[
462	                ("WRAPFILE_TEST_PARTIAL_WRITE", "1"),
463	                ("WRAPFILE_TEST_TRACE_BYTES", "1"),
464	            ],
465	            &trace,
466	        );
467	
468	        let on_disk = assert_success(&key, &run);
469	
470	        let events = parse_trace(&trace);
471	        let writes = successful_writes(&events);
472	        assert!(
473	            writes.len() >= KEY_LEN,
474	            "one-byte writes should mean at least 32 write() calls, got {}",
475	            writes.len()
476	        );
477	        // No written byte repeated, no later byte dropped...
478	        assert_writes_tile(&writes, KEY_LEN, "partial writes");
479	        // ...and the bytes the program handed to the kernel are exactly the
480	        // bytes that ended up in the file -- nothing reordered or invented.
