/*
 * keylife.c -- external ptrace observer for the keygen temporary-key
 * lifecycle regression tests.
 *
 * It is NOT an LD_PRELOAD shim and changes nothing in the observed program:
 * the test harness forks, the child PTRACE_TRACEME's itself and execs the
 * real wrapfile binary, and this program watches from outside. That lets a
 * regression test prove properties no black-box observation can -- deleting
 * the output file, keeping the key out of stdout/stderr, and exiting 0/1 are
 * all compatible with the 32 secret bytes never being wiped from the stack
 * (the process image vanishes on exit either way; a stack frame may also be
 * reused after the function returns). The memory holding the delivered bytes
 * therefore has to be inspected *while the operation is still in flight*.
 *
 * What is observed for one `wrapfile keygen <path>` run
 * ----------------------------------------------------
 * The key draw (getrandom(2); the getrandom crate issues it with inline
 * assembly, and under the tests the randtrap shim emulates it with a
 * SECCOMP_RET_TRAP SIGSYS handler), the key-file open/write/fsync/close
 * sequence, the user-space instruction at which the 32-byte buffer is
 * overwritten, and the first stdout/stderr write after that:
 *
 *   1. The 32-byte draw really is delivered into one buffer (address P):
 *      after the fill completes, [P, P+32) holds 32 *non-zero* bytes (the
 *      deterministic randtrap pattern, 0x80.. by draw index). A wipe that
 *      ran "successfully" on an all-zero buffer proves nothing.
 *   2. On the save path the same bytes are still there every time the key
 *      bytes are offered to write(2) on the key fd -- zeroing cannot have
 *      happened before/while saving (which would turn the saved file into an
 *      all-zero or truncated key) -- and they are still there when close(2)
 *      on the key fd returns on the success path.
 *   3. After that point the observer single-steps the guest and requires the
 *      whole 32-byte buffer to become zero within a bounded number of user
 *      instructions -- a tight byte-at-a-time loop, not a later frame reuse
 *      -- and before the program performs its first write(2) to stdout or
 *      stderr. A missing wipe, a wipe the optimizer deleted (the guest is
 *      inspected under both -O0 and -O2 builds), a wipe covering only part
 *      of the buffer, and a wipe placed before the save are all FAILs.
 *
 * Partial-draw failure needs one extra trick. When the random source dries
 * up after `held` (< 32) bytes, the remaining 32-held slots have never been
 * written by the source and stay zero from the array's zero initialization,
 * so inspecting buffer contents alone cannot tell a full-buffer wipe from a
 * wipe that only covers the delivered prefix. Immediately after observing
 * the emulated getrandom failure (while the guest is stopped), the observer
 * writes a non-zero sentinel pattern into [P+held, P+32) -- memory the
 * product never reads on the error path (getrandom already returned Err and
 * the command only returns from here). The wipe must then overwrite the
 * sentinel too.
 *
 * Output (stdout) is one `KEY=VALUE` event per line for the Rust harness:
 *
 *   EVENT name=FILL_COMPLETE held=32 secret=<hex>
 *   EVENT name=WRITE_BORROWS fd=N held=32
 *   EVENT name=CLOSE_STILL_HELD fd=N held=32
 *   EVENT name=WRITE_FAILED held=32
 *   EVENT name=RANDOM_FAILED held=N sentinel=M
 *   EVENT name=WIPED held=N sentinel=M steps=K
 *   EVENT name=OUTPUT_AFTER_WIPE fd=N
 *   EVENT name=GUEST_EXIT rc=N
 *   FAIL reason=...
 *
 * Exit status: 0 = every property for the requested mode held; 1 = a
 * regression was observed (FAIL line printed); 2 = usage/environment error.
 *
 * The guest's own stdout/stderr are redirected to capture files named on the
 * command line so the event stream stays parseable.
 *
 * Linux ptrace semantics relied on:
 *   - PTRACE_SEIZE is avoided in favour of TRACEME-from-child;
 *   - PTRACE_GET_SYSCALL_INFO distinguishes syscall-entry/exit stops even
 *     when a seccomp-trap SIGSYS is interleaved (a trapped syscall has no
 *     exit stop: ENTRY -> SIGSYS delivery -> handler -> rt_sigreturn, after
 *     which the signal frame holds the emulated return value and PC);
 *   - PTRACE_SINGLESTEP executes one user instruction; stepping onto/over a
 *     svc/syscall instruction runs the syscall and traps on the next user
 *     instruction, which is how syscalls occurring inside the wipe watch
 *     window (unlink/close/exit) are crossed without missing the wipe.
 *
 * Supported architectures: x86_64 and aarch64 (same set as the randtrap
 * shim). The build refuses anything else.
 */

#define _GNU_SOURCE
#include <elf.h>
#include <errno.h>
#include <fcntl.h>
#include <signal.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/ptrace.h>
#include <linux/ptrace.h>
#include <sys/uio.h>
#include <sys/wait.h>
#include <unistd.h>

#ifndef PTRACE_GET_SYSCALL_INFO
#define PTRACE_GET_SYSCALL_INFO 0x420e
#endif
#ifndef PTRACE_SYSCALL_INFO_NONE
#define PTRACE_SYSCALL_INFO_NONE 0
#define PTRACE_SYSCALL_INFO_ENTRY 1
#define PTRACE_SYSCALL_INFO_EXIT 2
#define PTRACE_SYSCALL_INFO_SECCOMP 3
#endif

#if defined(__aarch64__)
#include <asm/ptrace.h>
typedef struct user_pt_regs gregs_t;
#define GREG_NT NT_PRSTATUS
#define SYS_rt_sigreturn_local 139
static long greg_nr(const gregs_t *g) { return (long)g->regs[8]; }
static long greg_arg(const gregs_t *g, int i) { return (long)g->regs[i]; }
static long greg_ret(const gregs_t *g) { return (long)g->regs[0]; }
static unsigned long greg_pc(const gregs_t *g) { return g->pc; }
/* svc #imm: 1101 0100 000x xxxx xxxx xxxx xx00 0001 */
static int is_syscall_insn(uint32_t insn)
{
    return (insn & 0xffe0001fu) == 0xd4000001u;
}
#define SYS_INSN_SIZE 4
#elif defined(__x86_64__)
#include <sys/user.h>
typedef struct user_regs_struct gregs_t;
#define GREG_NT NT_PRSTATUS
#define SYS_rt_sigreturn_local 15
static long greg_nr(const gregs_t *g) { return (long)g->orig_rax; }
static long greg_arg(const gregs_t *g, int i)
{
    switch (i) {
    case 0: return (long)g->rdi;
    case 1: return (long)g->rsi;
    case 2: return (long)g->rdx;
    case 3: return (long)g->r10;
    case 4: return (long)g->r8;
    default: return (long)g->r9;
    }
}
static long greg_ret(const gregs_t *g) { return (long)g->rax; }
static unsigned long greg_pc(const gregs_t *g) { return g->rip; }
/* syscall: 0f 05 */
static int is_syscall_insn(uint16_t insn) { return insn == 0x050fu; }
#define SYS_INSN_SIZE 2
#else
#error "keylife supports x86_64 and aarch64 only"
#endif

/* write/writev/exit_group numbers are stable across the two arches. */
#ifndef SYS_write
#define SYS_write 1
#endif
#ifndef SYS_writev
#define SYS_writev 20
#endif
#ifndef SYS_exit_group
#define SYS_exit_group 231
#endif
#ifndef SYS_getrandom
#if defined(__x86_64__)
#define SYS_getrandom 318
#else
#define SYS_getrandom 278
#endif
#endif
#ifndef SYS_openat
#define SYS_openat 257
#endif
#ifndef SYS_close
#define SYS_close 3
#endif

#define KEYN 32

/* Upper bound on user instructions between the wipe watch arm point and
 * the buffer being fully zero. The real wipe loop is a few hundred
 * instructions at -O0 and fewer at -O2; the generous bound only exists to
 * turn a missing wipe into a fast FAIL instead of a single-step marathon to
 * process exit. */
#define WIPE_STEP_BUDGET 4000000L

enum mode { MODE_SUCCESS, MODE_RANDFAIL, MODE_WRITEFAIL };

struct observer {
    pid_t pid;
    enum mode mode;

    uint64_t p;                 /* address of the guest's 32-byte buffer */
    int phase;                  /* 0 pre-fill, 1 filling, 2 filled,
                                   3 random failed, 4 wipe armed, 5 wiped */
    int held;                   /* pattern prefix currently at [p, p+32) */
    int sentinel;               /* number of sentinel bytes planted */
    uint8_t secret[KEYN];       /* observed full key (filled phases) */
    int keyfd;                  /* fd of the key file, or -1 */
    int saw_output;             /* stdout/stderr write already observed */
    int output_after_wipe;
    int fill_req_seen;
    int fill_req32_seen;
    int wipe_reported;
    long wipe_steps;
    int failed;
    char fail_reason[256];

    /* pending syscall-entry state */
    int entry_valid;
    long entry_nr;
    uint64_t entry_a0, entry_a1, entry_a2;
};

static void die_usage(void)
{
    fprintf(stderr,
        "usage: keylife <success|randfail|writefail> <stdout-cap> <stderr-cap>"
        " -- <guest> [args...]\n");
    exit(2);
}

static void set_fail(struct observer *o, const char *fmt, ...)
{
    if (o->failed)
        return;
    va_list ap;
    va_start(ap, fmt);
    o->failed = 1;
    vsnprintf(o->fail_reason, sizeof o->fail_reason, fmt, ap);
    va_end(ap);
    printf("FAIL reason=%s\n", o->fail_reason);
    fflush(stdout);
}

/* ---- remote memory ---- */

static int remote_read(struct observer *o, uint64_t addr, void *buf, size_t n)
{
    struct iovec local = { buf, n };
    struct iovec remote = { (void *)addr, n };
    return process_vm_readv(o->pid, &local, 1, &remote, 1, 0) == (ssize_t)n
               ? 0
               : -1;
}

static int remote_write(struct observer *o, uint64_t addr, const void *buf,
                        size_t n)
{
    struct iovec local = { (void *)buf, n };
    struct iovec remote = { (void *)addr, n };
    return process_vm_writev(o->pid, &local, 1, &remote, 1, 0) == (ssize_t)n
               ? 0
               : -1;
}

static void get_gregs(struct observer *o, gregs_t *g)
{
    struct iovec iov = { g, sizeof *g };
    if (ptrace(PTRACE_GETREGSET, o->pid, (void *)GREG_NT, &iov) < 0) {
        set_fail(o, "PTRACE_GETREGSET: %s", strerror(errno));
    }
}

static int read_insn(struct observer *o, unsigned long pc,
                     unsigned long *insn)
{
    /* Read a little extra so both 2-byte (x86 syscall) and 4-byte
     * (aarch64 svc) encodings are covered by one read. */
    unsigned char bytes[8] = {0};
    if (remote_read(o, pc, bytes, sizeof bytes) != 0)
        return -1;
    memcpy(insn, bytes, sizeof *insn);
    return 0;
}

/* ---- the randtrap delivery pattern ---- */

static uint8_t pattern_next(uint8_t b)
{
    return (uint8_t)(0x80 + (((unsigned)b - 0x80u + 1u) % 64u));
}

/* Length of the contiguous non-zero pattern prefix the random source left in
 * buf: starts with any 0x80..0xBF byte, each next byte advances by one
 * modulo the pattern period, and undelivered slots are still zero (which
 * terminates the run). */
static int pattern_prefix(const uint8_t *buf)
{
    int i = 0;
    if (buf[0] < 0x80 || buf[0] >= 0xc0)
        return 0;
    while (i < KEYN && buf[i] != 0) {
        if (i > 0 && buf[i] != pattern_next(buf[i - 1]))
            break;
        i++;
    }
    return i;
}

static int all_zero(const uint8_t *buf, int n)
{
    for (int i = 0; i < n; i++)
        if (buf[i])
            return 0;
    return 1;
}

static void print_hex(const uint8_t *buf, int n)
{
    for (int i = 0; i < n; i++)
        printf("%02x", buf[i]);
}

static void event_simple(const char *name)
{
    printf("EVENT name=%s\n", name);
    fflush(stdout);
}

/* ---- buffer classification at a stop ---- */

static int read_keybuf(struct observer *o, uint8_t out[KEYN])
{
    memset(out, 0, KEYN);
    if (!o->p)
        return -1;
    return remote_read(o, o->p, out, KEYN);
}

/* Verify the whole 32-byte buffer still equals the observed key. Used while
 * the save borrows the buffer: a premature wipe fails here. */
static void require_still_holds_full_key(struct observer *o, const char *what,
                                         int fd)
{
    uint8_t cur[KEYN];
    if (read_keybuf(o, cur) != 0) {
        set_fail(o, "%s: cannot read key buffer", what);
        return;
    }
    if (memcmp(cur, o->secret, KEYN) != 0) {
        set_fail(o,
                 "%s fd=%d: key buffer changed before the save finished",
                 what, fd);
        return;
    }
    printf("EVENT name=%s fd=%d held=%d\n", what, fd, KEYN);
    fflush(stdout);
}

/* Recompute the pattern prefix currently present and update held. Called
 * after every completion of a getrandom that belongs to the key fill. */
static void refresh_fill(struct observer *o, long ret)
{
    uint8_t cur[KEYN];
    if (read_keybuf(o, cur) != 0) {
        set_fail(o, "cannot read key buffer after getrandom");
        return;
    }
    int pre = pattern_prefix(cur);

    if (ret < 0) {
        if (o->mode == MODE_RANDFAIL) {
            if (pre <= 0 || pre >= KEYN) {
                set_fail(o,
                         "randfail scenario expected a partial delivery "
                         "(1..31 bytes), got prefix=%d ret=%ld",
                         pre, ret);
                return;
            }
            o->held = pre;
            /* Plant a non-zero sentinel over the slots the source never
             * delivered: the product cannot read them on this error path,
             * and a full-buffer wipe must erase them too. Position-derived
             * non-zero bytes, outside the 0x80..0xBF pattern band. */
            uint8_t sent[KEYN];
            int m = KEYN - pre;
            for (int i = 0; i < m; i++)
                sent[i] =
                    (uint8_t)(0xd0 + ((unsigned)(i * 5 + pre + 1) & 0x0f));
            if (remote_write(o, o->p + (uint64_t)pre, sent, (size_t)m) !=
                0) {
                set_fail(o, "cannot plant sentinel in undelivered tail");
                return;
            }
            o->sentinel = m;
            memcpy(o->secret, cur, KEYN);
            o->phase = 4;
            o->wipe_steps = 0;
            printf("EVENT name=RANDOM_FAILED held=%d sentinel=%d\n", pre, m);
            fflush(stdout);
        } else {
            set_fail(o,
                     "unexpected getrandom failure (ret=%ld) in mode %d",
                     ret, (int)o->mode);
        }
        return;
    }

    o->held = pre;
    if (pre == KEYN) {
        memcpy(o->secret, cur, KEYN);
        o->phase = 2;
        printf("EVENT name=FILL_COMPLETE held=32 secret=");
        print_hex(cur, KEYN);
        putchar('\n');
        fflush(stdout);
    } else if (o->phase < 2 && o->fill_req32_seen) {
        /* Short reads still in progress: nothing to report, keep filling. */
        o->phase = 1;
    }
}

/* A getrandom completion seen by the tracer. `ret` is the value the guest
 * observes (kernel return or emulated SIGSYS value). */
static void on_getrandom_done(struct observer *o, long ret)
{
    if (!o->fill_req32_seen || o->phase >= 2)
        return;
    refresh_fill(o, ret);
}

/* ---- syscall-entry/exit handling while not wipe-watching ---- */

static void on_syscall_entry(struct observer *o, const gregs_t *g,
                             const struct ptrace_syscall_info *si)
{
    long nr = (long)si->entry.nr;
    o->entry_valid = 1;
    o->entry_nr = nr;
    o->entry_a0 = (uint64_t)si->entry.args[0];
    o->entry_a1 = (uint64_t)si->entry.args[1];
    o->entry_a2 = (uint64_t)si->entry.args[2];

    if (nr == SYS_getrandom) {
        unsigned long len = (unsigned long)si->entry.args[1];
        if (len == KEYN) {
            /* The 32-byte request identifies keygen's own fill (the crate's
             * zero-length probe and the runtime's startup draws use other
             * lengths); the fill is the last such request in the process. */
            o->p = (uint64_t)si->entry.args[0];
            o->fill_req32_seen = 1;
            o->phase = 1;
            o->held = 0;
            o->sentinel = 0;
        }
        o->fill_req_seen = 1;
        return;
    }

    if (nr == SYS_write || nr == SYS_writev) {
        long fd = (long)si->entry.args[0];
        if (o->phase >= 2 && o->keyfd >= 0 && fd == (long)o->keyfd) {
            /* The bytes offered to the key fd must still be the real key;
             * read them from the user pointer to prove the save is
             * borrowing live secret material, not zeros. */
            uint8_t offered[KEYN];
            size_t want = (size_t)si->entry.args[1] ? 0 : 0;
            (void)want;
            if (remote_read(o, (uint64_t)si->entry.args[1], offered,
                            KEYN) == 0) {
                if (all_zero(offered, KEYN)) {
                    set_fail(o,
                             "write to key fd offered all-zero bytes: wipe "
                             "ran before/during the save");
                }
            }
            require_still_holds_full_key(o, "WRITE_BORROWS", o->keyfd);
        }
    }

    (void)g;
}

static void on_syscall_exit(struct observer *o, const gregs_t *g,
                            const struct ptrace_syscall_info *si)
{
    long rval = (long)si->exit.rval;
    int iserr = si->exit.is_error;

    if (!o->entry_valid)
        return;

    switch (o->entry_nr) {
    case SYS_getrandom:
        on_getrandom_done(o, iserr ? rval : rval);
        break;

    case SYS_openat:
        /* The first successful openat after the fill is the key file's
         * O_CREAT|O_EXCL open (the draw strictly precedes it). */
        if (o->phase >= 2 && o->keyfd < 0 && !iserr && rval >= 0) {
            o->keyfd = (int)rval;
        }
        break;

    case SYS_write:
    case SYS_writev:
        if (o->phase == 2 && o->keyfd >= 0 &&
            (long)o->entry_a0 == (long)o->keyfd && o->mode == MODE_WRITEFAIL &&
            iserr) {
            /* Mid-save unrecoverable write failure with the full key still
             * in memory: arm the wipe watch. unlink/close/format happen in
             * this window; the wipe must land before the stderr report. */
            uint8_t cur[KEYN];
            if (read_keybuf(o, cur) == 0 &&
                memcmp(cur, o->secret, KEYN) != 0) {
                set_fail(o,
                         "key buffer was altered before the failed-write "
                         "error path");
                break;
            }
            printf("EVENT name=WRITE_FAILED held=%d\n", KEYN);
            fflush(stdout);
            o->phase = 4;
            o->held = KEYN;
            o->sentinel = 0;
            o->wipe_steps = 0;
        }
        break;

    case SYS_close:
        if (o->mode == MODE_SUCCESS && o->phase == 2 && o->keyfd >= 0 &&
            (long)o->entry_a0 == (long)o->keyfd && !iserr) {
            require_still_holds_full_key(o, "CLOSE_STILL_HELD", o->keyfd);
            if (!o->failed) {
                o->phase = 4;
                o->held = KEYN;
                o->sentinel = 0;
                o->wipe_steps = 0;
            }
        }
        break;
    }

    o->entry_valid = 0;
    (void)g;
}

/* ---- SIGSYS (seccomp-emulated getrandom) handling ---- */

/* The randtrap shim emulates a trapped getrandom in a SIGSYS handler:
 * delivery-stop -> handler runs (its own trace write) -> rt_sigreturn ->
 * guest resumes right after the svc with the emulated value in the return
 * register. Drive that mini-protocol and, on rt_sigreturn exit, hand the
 * emulated result to the fill tracker. Returns 0 on a handled stop, -1 if
 * the guest died. */
static int drive_sigsys(struct observer *o)
{
    int status;
    for (;;) {
        if (ptrace(PTRACE_SYSCALL, o->pid, 0, (void *)(long)SIGSYS) < 0) {
            set_fail(o, "ptrace inject SIGSYS: %s", strerror(errno));
            return -1;
        }
        if (waitpid(o->pid, &status, 0) < 0) {
            set_fail(o, "waitpid in SIGSYS: %s", strerror(errno));
            return -1;
        }
        if (WIFEXITED(status) || WIFSIGNALED(status))
            return -1;
        if (!WIFSTOPPED(status))
            continue;
        int sig = WSTOPSIG(status);
        if (sig == (SIGTRAP | 0x80)) {
            struct ptrace_syscall_info si;
            memset(&si, 0, sizeof si);
            if (ptrace(PTRACE_GET_SYSCALL_INFO, o->pid, sizeof si, &si) < 0)
                continue;
            if (si.op == PTRACE_SYSCALL_INFO_ENTRY &&
                (long)si.entry.nr == SYS_rt_sigreturn_local) {
                /* Wait for rt_sigreturn exit: the restored frame now holds
                 * the emulated getrandom result in the return register. */
                if (ptrace(PTRACE_SYSCALL, o->pid, 0, 0) < 0)
                    return -1;
                if (waitpid(o->pid, &status, 0) < 0)
                    return -1;
                if (WIFEXITED(status) || WIFSIGNALED(status))
                    return -1;
                gregs_t g;
                get_gregs(o, &g);
                if (o->failed)
                    return -1;
                long emulated = greg_ret(&g);
                if (o->fill_req_seen)
                    on_getrandom_done(o, emulated);
                return 0;
            }
        } else if (sig == SIGSYS) {
            /* Nested trap while delivering: try again. */
            continue;
        }
    }
}

/* ---- wipe watch (single-stepping) ---- */

/* Inspect the buffer at a single-step trap. Returns 1 while still armed. */
static int watch_step(struct observer *o, const gregs_t *g)
{
    o->wipe_steps++;
    if (o->wipe_steps > WIPE_STEP_BUDGET) {
        set_fail(o,
                 "key buffer was not zeroed within %ld user instructions",
                 WIPE_STEP_BUDGET);
        return 0;
    }

    unsigned long pc = greg_pc(g);
    unsigned long insn = 0;
    int at_syscall = (read_insn(o, pc, &insn) == 0) &&
                     is_syscall_insn((uint32_t)insn) &&
                     greg_nr(g) == greg_nr(g); /* pc-bound instruction */
    (void)at_syscall;

    /* The trap for the instruction at pc fires before it executes, so a
     * syscall at pc can be inspected by its entry arguments. */
    long nr = greg_nr(g);
    if ((nr == SYS_write || nr == SYS_writev) &&
        read_insn(o, pc, &insn) == 0 && is_syscall_insn((uint32_t)insn)) {
        long fd = greg_arg(g, 0);
        if (fd == 1 || fd == 2) {
            uint8_t cur[KEYN];
            int wiped = (read_keybuf(o, cur) == 0) && all_zero(cur, KEYN);
            if (!wiped) {
                set_fail(o,
                         "guest wrote to fd %ld (stdout/stderr) before the "
                         "key buffer was zeroed",
                         fd);
                return 0;
            }
            if (!o->output_after_wipe) {
                o->output_after_wipe = 1;
                printf("EVENT name=OUTPUT_AFTER_WIPE fd=%ld\n", fd);
                fflush(stdout);
            }
        }
    }
    if (nr == SYS_exit_group) {
        uint8_t cur[KEYN];
        int wiped = (read_keybuf(o, cur) == 0) && all_zero(cur, KEYN);
        if (!wiped) {
            set_fail(o,
                     "guest reached exit_group with the key buffer not "
                     "zeroed (held=%d sentinel=%d)",
                     o->held, o->sentinel);
            return 0;
        }
    }

    if (!o->wipe_reported) {
        uint8_t cur[KEYN];
        if (read_keybuf(o, cur) == 0) {
            /* The whole buffer must be zero: delivered prefix and any
             * planted sentinel alike. */
            if (all_zero(cur, KEYN)) {
                o->wipe_reported = 1;
                o->phase = 5;
                printf("EVENT name=WIPED held=%d sentinel=%d steps=%ld\n",
                       o->held, o->sentinel, o->wipe_steps);
                fflush(stdout);
                /* Disarm: the remainder of the process is followed with
                 * ordinary syscall stops. */
                return 0;
            }
        }
    }
    return o->wipe_reported ? 0 : 1;
}

/* ---- child setup ---- */

static void run_child(char **argv, const char *out_cap, const char *err_cap)
{
    int outfd = open(out_cap, O_WRONLY | O_CREAT | O_TRUNC, 0600);
    if (outfd < 0)
        _exit(126);
    int errfd = open(err_cap, O_WRONLY | O_CREAT | O_TRUNC, 0600);
    if (errfd < 0)
        _exit(126);
    dup2(outfd, STDOUT_FILENO);
    dup2(errfd, STDERR_FILENO);
    if (outfd > STDERR_FILENO)
        close(outfd);
    if (errfd > STDERR_FILENO)
        close(errfd);

    ptrace(PTRACE_TRACEME, 0, 0, 0);
    raise(SIGSTOP);
    execv(argv[0], argv);
    _exit(127);
}

int main(int argc, char **argv)
{
    if (argc < 6)
        die_usage();
    enum mode mode;
    if (!strcmp(argv[1], "success"))
        mode = MODE_SUCCESS;
    else if (!strcmp(argv[1], "randfail"))
        mode = MODE_RANDFAIL;
    else if (!strcmp(argv[1], "writefail"))
        mode = MODE_WRITEFAIL;
    else
        die_usage();
    const char *out_cap = argv[2];
    const char *err_cap = argv[3];
    if (strcmp(argv[4], "--") != 0)
        die_usage();
    char **guest_argv = &argv[5];

    struct observer o;
    memset(&o, 0, sizeof o);
    o.mode = mode;
    o.keyfd = -1;
    o.phase = 0;

    pid_t pid = fork();
    if (pid < 0) {
        perror("fork");
        return 2;
    }
    if (pid == 0)
        run_child(guest_argv, out_cap, err_cap);
    o.pid = pid;

    int status;
    if (waitpid(pid, &status, WUNTRACED) < 0) {
        perror("waitpid initial");
        return 2;
    }
    if (ptrace(PTRACE_SETOPTIONS, pid, 0, PTRACE_O_TRACESYSGOOD) < 0) {
        fprintf(stderr, "PTRACE_SETOPTIONS: %s\n", strerror(errno));
        return 2;
    }

    int stepping = 0;
    for (;;) {
        long request = stepping ? PTRACE_SINGLESTEP : PTRACE_SYSCALL;
        if (ptrace(request, pid, 0, 0) < 0) {
            if (errno == ESRCH)
                break;
            set_fail(&o, "ptrace continue: %s", strerror(errno));
            break;
        }
        if (waitpid(pid, &status, 0) < 0) {
            set_fail(&o, "waitpid: %s", strerror(errno));
            break;
        }
        if (WIFEXITED(status)) {
            printf("EVENT name=GUEST_EXIT rc=%d\n", WEXITSTATUS(status));
            fflush(stdout);
            break;
        }
        if (WIFSIGNALED(status)) {
            set_fail(&o, "guest killed by signal %d", WTERMSIG(status));
            break;
        }
        if (!WIFSTOPPED(status)) {
            set_fail(&o, "unexpected wait status 0x%x", status);
            break;
        }
        int sig = WSTOPSIG(status);

        if (stepping) {
            gregs_t g;
            get_gregs(&o, &g);
            if (o.failed)
                break;
            /* Single-stepping executes a syscall instruction and traps on
             * the next user instruction; no special crossing is needed.
             * An unexpected SIGSYS cannot occur this late (all draws are
             * done), but drive it correctly just in case. */
            if (sig == SIGSYS) {
                if (drive_sigsys(&o) < 0)
                    break;
                continue;
            }
            if (sig != SIGTRAP && sig != (SIGTRAP | 0x80)) {
                /* Some other signal: reinject and keep stepping. */
                if (ptrace(PTRACE_SINGLESTEP, pid, 0,
                           (void *)(long)sig) < 0) {
                    set_fail(&o, "reinject signal %d", sig);
                    break;
                }
                waitpid(pid, &status, 0);
                continue;
            }
            if (!watch_step(&o, &g))
                stepping = 0;
            continue;
        }

        if (sig == SIGSYS) {
            if (drive_sigsys(&o) < 0)
                break;
            if (o.phase == 4 && !o.failed)
                stepping = 1;
            continue;
        }

        if (sig != (SIGTRAP | 0x80)) {
            /* Deliver genuine signals (e.g. SIGCHLD does not stop here) and
             * keep tracing. */
            if (ptrace(PTRACE_SYSCALL, pid, 0, (void *)(long)sig) < 0) {
                set_fail(&o, "reinject %d: %s", sig, strerror(errno));
                break;
            }
            continue;
        }

        struct ptrace_syscall_info si;
        memset(&si, 0, sizeof si);
        if (ptrace(PTRACE_GET_SYSCALL_INFO, pid, sizeof si, &si) < 0) {
            set_fail(&o, "PTRACE_GET_SYSCALL_INFO: %s", strerror(errno));
            break;
        }

        gregs_t g;
        get_gregs(&o, &g);
        if (o.failed)
            break;

        if (si.op == PTRACE_SYSCALL_INFO_ENTRY) {
            on_syscall_entry(&o, &g, &si);
        } else if (si.op == PTRACE_SYSCALL_INFO_EXIT) {
            on_syscall_exit(&o, &g, &si);
        }
        if (o.failed)
            break;
        if (o.phase == 4)
            stepping = 1;
    }

    /* Final scenario-specific coherence checks. */
    if (!o.failed) {
        if (o.phase != 5) {
            set_fail(&o,
                     "wipe watch never completed (phase=%d held=%d "
                     "sentinel=%d)",
                     o.phase, o.held, o.sentinel);
        } else if (!o.output_after_wipe) {
            set_fail(&o,
                     "buffer was wiped but no post-wipe stdout/stderr "
                     "write was observed");
        } else if (mode == MODE_SUCCESS && o.keyfd < 0) {
            set_fail(&o, "success path never opened the key file");
        } else if (mode == MODE_RANDFAIL && o.sentinel == 0) {
            set_fail(&o, "randfail path never planted the tail sentinel");
        } else if (mode == MODE_WRITEFAIL && o.keyfd < 0) {
            set_fail(&o, "writefail path never opened the key file");
        }
    }

    /* Detach/kill is unnecessary: the guest either exited or will exit on
     * its own; if we failed mid-run, terminate it to avoid a stray tracer
     * dependency. */
    if (o.failed) {
        kill(pid, SIGKILL);
        waitpid(pid, &status, 0);
    }

    return o.failed ? 1 : 0;
}

